MOD = 10**9 + 7


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in the inclusive range whose digit sum is in the requested interval."""
    def count_up_to(bound: str) -> int:
        # dp holds prefixes already below the bound; tight holds equal prefixes.
        dp = [0] * (max_sum + 1)
        tight = [0] * (max_sum + 1)
        tight[0] = 1

        for ch in bound:
            limit = int(ch)
            next_dp = [0] * (max_sum + 1)
            next_tight = [0] * (max_sum + 1)

            for total, ways in enumerate(dp):
                if ways:
                    for digit in range(10):
                        new_total = total + digit
                        if new_total <= max_sum:
                            next_dp[new_total] = (next_dp[new_total] + ways) % MOD

            for total, ways in enumerate(tight):
                if ways:
                    for digit in range(limit + 1):
                        new_total = total + digit
                        if new_total > max_sum:
                            continue
                        if digit == limit:
                            next_tight[new_total] = (next_tight[new_total] + ways) % MOD
                        else:
                            next_dp[new_total] = (next_dp[new_total] + ways) % MOD

            dp, tight = next_dp, next_tight

        return (sum(dp[min_sum:]) + sum(tight[min_sum:])) % MOD

    def decrement(value: str):
        digits = list(value)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        return "".join(digits).lstrip("0") or "0"

    before = decrement(num1)
    lower_count = count_up_to(before) if before is not None else 0
    return (count_up_to(num2) - lower_count) % MOD

