from typing import List


MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Given a lowercase English string s of length n and an integer m,
    count length-m lowercase strings by their LCS length with s.
    """
    # A bit at position i means that the LCS length for s[:i + 1]
    # increases by one relative to s[:i]. These increments encode the
    # entire dynamic-programming row.
    char_masks = [0] * 26
    for i, ch in enumerate(s):
        char_masks[ord(ch) - ord("a")] |= 1 << i

    counts = {0: 1}
    for _ in range(m):
        next_counts = {}
        for state, ways in counts.items():
            for mask in char_masks:
                union = state | mask
                shifted = (state << 1) | 1
                new_state = union & ~(union - shifted)
                next_counts[new_state] = (next_counts.get(new_state, 0) + ways) % MOD
        counts = next_counts

    result = [0] * (n + 1)
    for state, ways in counts.items():
        result[state.bit_count()] = (result[state.bit_count()] + ways) % MOD
    return result

