def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    mod = 998244353

    # Every constant word a^M has to occur, except when it is X itself.
    # Their required multiplicities give a useful necessary length bound.
    required = [M] * K
    if len(X) == M and all(value == X[0] for value in X):
        required[X[0] - 1] -= 1
    if N < sum(required):
        return 0

    # Number all length-M words in base K. A bit is set once that word has
    # appeared as a subsequence.
    word_count = K ** M
    wanted = (1 << word_count) - 1
    x_id = 0
    for value in X:
        x_id = x_id * K + (value - 1)
    wanted ^= 1 << x_id

    # A new length-M subsequence can only be created by appending a symbol to
    # the previous M-1 symbols. Thus a state needs the seen-word bitset and
    # that bounded suffix.
    states = {(0, 0, 0): 1}
    suffix_modulus = K ** max(0, M - 2)
    for _ in range(N):
        following = {}
        for (seen, suffix, suffix_len), ways in states.items():
            for digit in range(K):
                new_seen = seen
                if suffix_len == M - 1:
                    new_seen |= 1 << (suffix * K + digit)

                new_len = min(M - 1, suffix_len + 1)
                if suffix_len < M - 1:
                    new_suffix = suffix * K + digit
                else:
                    new_suffix = (suffix % suffix_modulus) * K + digit

                key = (new_seen, new_suffix, new_len)
                following[key] = (following.get(key, 0) + ways) % mod
        states = following

    return sum(ways for (seen, _suffix, _length), ways in states.items()
               if seen == wanted) % mod

