def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences modulo 998244353.

    The in-degree vectors of orientations of a graph are the lattice points
    of its graphical zonotope. For a graphic matroid, these lattice points
    are counted by the independent edge sets, which are exactly the forests.
    This graph has a cycle plus spokes to the extra vertex, so a path
    decomposition with the extra vertex and one cycle endpoint in the
    frontier counts its forests using only a constant number of states.
    """
    mod = 998244353

    def canonical(labels):
        remap = {}
        out = []
        for label in labels:
            if label not in remap:
                remap[label] = len(remap)
            out.append(remap[label])
        return tuple(out)

    def add_edge(state, a, b):
        """Add an edge between frontier positions; None signals a cycle."""
        if state[a] == state[b]:
            return None
        old = state[b]
        new = state[a]
        return canonical([new if x == old else x for x in state])

    # State labels describe connectivity among (hub, vertex 0, current).
    # Initialize by optionally choosing the spoke at 0 and cycle edge (0, 1).
    dp = {}
    initial = (0, 1, 2)
    for spoke in (0, 1) if s[0] == '1' else (0,):
        st = initial
        if spoke:
            st = add_edge(st, 0, 1)
        for cycle_edge in (0, 1):
            nxt = add_edge(st, 1, 2) if cycle_edge else st
            if nxt is not None:
                dp[nxt] = (dp.get(nxt, 0) + 1) % mod

    # Introduce vertices 2 through n-1. At each step, optionally choose the
    # current vertex's spoke and the next cycle edge, then forget the old
    # current vertex while retaining hub and vertex 0 for the closing edge.
    for i in range(1, n - 1):
        ndp = {}
        for state, ways in dp.items():
            expanded = canonical([state[0], state[1], state[2], 3])
            spoke_options = (0, 1) if s[i] == '1' else (0,)
            for spoke in spoke_options:
                st = add_edge(expanded, 0, 2) if spoke else expanded
                if st is None:
                    continue
                for cycle_edge in (0, 1):
                    nxt = add_edge(st, 2, 3) if cycle_edge else st
                    if nxt is None:
                        continue
                    reduced = canonical([nxt[0], nxt[1], nxt[3]])
                    ndp[reduced] = (ndp.get(reduced, 0) + ways) % mod
        dp = ndp

    # Add the last spoke and the closing cycle edge (n-1, 0).
    answer = 0
    for state, ways in dp.items():
        spoke_options = (0, 1) if s[n - 1] == '1' else (0,)
        for spoke in spoke_options:
            st = add_edge(state, 0, 2) if spoke else state
            if st is None:
                continue
            for closing_edge in (0, 1):
                final = add_edge(st, 1, 2) if closing_edge else st
                if final is not None:
                    answer = (answer + ways) % mod
    return answer

