from bisect import bisect_right
from functools import lru_cache
from math import isqrt


_MAX_N = 10**18


def _integer_root(n: int, exponent: int) -> int:
    """Return floor(n ** (1 / exponent)) using integer arithmetic."""
    low, high = 1, 1 << ((n.bit_length() + exponent - 1) // exponent)
    while low < high:
        mid = (low + high + 1) // 2
        if mid**exponent <= n:
            low = mid
        else:
            high = mid - 1
    return low


@lru_cache(maxsize=1)
def _nonsquare_powers():
    # A perfect power that is not a square has an odd factor in its
    # canonical exponent, so it is a^e for some odd e >= 3.
    values = set()
    for exponent in range(3, _MAX_N.bit_length(), 2):
        for base in range(2, _integer_root(_MAX_N, exponent) + 1):
            value = base**exponent
            root = isqrt(value)
            if root * root != value:
                values.add(value)
    return sorted(values)


def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    return isqrt(n) + bisect_right(_nonsquare_powers(), n)

