MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product is a good integer at most N.

    An integer is good when its divisor sum is divisible by 3.
    """
    if N < 1 or M < 1:
        return 0

    # For n = product(p**e), the number of ordered length-M factorizations
    # is product_p binom(M + e - 1, e).  The divisor sum is multiplicative;
    # its p**e factor is 1+p+...+p**e modulo 3.
    max_exp = N.bit_length()
    weights = [1] * (max_exp + 1)
    for e in range(1, max_exp + 1):
        weights[e] = weights[e - 1] * (M + e - 1) % MOD
        weights[e] = weights[e] * pow(e, MOD - 2, MOD) % MOD

    limit = int(N ** 0.5)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    answer = 0
    block_size = 500_000
    for low in range(1, N + 1, block_size):
        high = min(N, low + block_size - 1)
        size = high - low + 1
        rem = list(range(low, high + 1))
        ways = [1] * size
        good = bytearray(size)

        for p in primes:
            if p * p > high:
                break
            first = ((low + p - 1) // p) * p
            for v in range(first, high + 1, p):
                i = v - low
                if rem[i] % p:
                    continue
                e = 0
                r = rem[i]
                while r % p == 0:
                    r //= p
                    e += 1
                rem[i] = r
                ways[i] = ways[i] * weights[e] % MOD
                if p % 3 == 1:
                    if e % 3 == 2:
                        good[i] = 1
                elif p % 3 == 2 and e % 2 == 1:
                    good[i] = 1

        for i, r in enumerate(rem):
            if r > 1:
                ways[i] = ways[i] * M % MOD
                if r % 3 == 2:
                    good[i] = 1
        answer = (answer + sum(ways[i] for i in range(size) if good[i])) % MOD
    return answer

