from typing import List


MOD = 998244353


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Given lowercase string s, count length-m strings by LCS length with s."""
    # The DP row for LCS(s, t) after reading t fully determines its update
    # after one more character. Its entries are the LCS lengths against each
    # prefix of s.
    states = {(0,) * (n + 1): 1}
    letters = set(s)
    absent_count = 26 - len(letters)

    for _ in range(m):
        next_states = {}
        for row, ways in states.items():
            if absent_count:
                next_states[row] = (next_states.get(row, 0) + ways * absent_count) % MOD
            for ch in letters:
                updated = [0] * (n + 1)
                for i in range(1, n + 1):
                    best = row[i]
                    if updated[i - 1] > best:
                        best = updated[i - 1]
                    if s[i - 1] == ch and row[i - 1] + 1 > best:
                        best = row[i - 1] + 1
                    updated[i] = best
                key = tuple(updated)
                next_states[key] = (next_states.get(key, 0) + ways) % MOD
        states = next_states

    result = [0] * (n + 1)
    for row, ways in states.items():
        result[row[n]] = (result[row[n]] + ways) % MOD
    return result

