from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if h <= 0 or w <= 0 or n < 0 or len(tiles) < n:
        return False
    tiles = tiles[:n]
    area = h * w
    tile_areas = [a * b for a, b in tiles]

    # If no subset of available tile areas adds up to the grid area, no tiling
    # can cover the grid.
    possible_areas = {0}
    for tile_area in tile_areas:
        possible_areas |= {x + tile_area for x in tuple(possible_areas)}
    if area not in possible_areas:
        return False

    # Represent occupied cells by bits in a Python integer.
    full = (1 << area) - 1
    placements = []
    for a, b in tiles:
        orientations = {(a, b), (b, a)}
        masks = []
        for ph, pw in orientations:
            if ph <= h and pw <= w:
                for r in range(h - ph + 1):
                    for c in range(w - pw + 1):
                        mask = 0
                        for rr in range(r, r + ph):
                            mask |= ((1 << pw) - 1) << (rr * w + c)
                        masks.append(mask)
        placements.append(tuple(set(masks)))

    subset_area = [0] * (1 << n)
    for mask in range(1, 1 << n):
        bit = mask & -mask
        subset_area[mask] = subset_area[mask ^ bit] + tile_areas[bit.bit_length() - 1]

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True

        empty_count = area - occupied.bit_count()
        # At least one subset of the unused tiles must have exactly the area
        # left to cover.
        remaining = ((1 << n) - 1) ^ used
        sub = remaining
        area_possible = False
        while True:
            if subset_area[sub] == empty_count:
                area_possible = True
                break
            if sub == 0:
                break
            sub = (sub - 1) & remaining
        if not area_possible:
            return False

        # The first uncovered cell must be the top-left cell of the next tile:
        # any rectangle reaching it from above or from the left would overlap
        # an already occupied cell.
        bitpos = next(i for i in range(area) if not (occupied >> i) & 1)
        r, c = divmod(bitpos, w)
        for i in range(n):
            if (used >> i) & 1:
                continue
            for mask in placements[i]:
                if mask & (1 << bitpos) and not (mask & occupied):
                    if search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

