from bisect import bisect_right
from functools import lru_cache
from math import isqrt

MOD = 998244353


def _prime_data(n):
    limit = isqrt(n)
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0] = 0
    if limit:
        sieve[1] = 0
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * (((limit - start) // p) + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    values = []
    left = 1
    while left <= n:
        v = n // left
        values.append(v)
        left = n // v + 1
    pos = {v: i for i, v in enumerate(values)}
    total = [v - 1 for v in values]

    def chi_prefix(x):
        return 1 if x % 3 == 1 else 0

    character = [chi_prefix(v) - 1 for v in values]
    count_before = character_before = 0
    for p in primes:
        p2 = p * p
        chi_p = 1 if p % 3 == 1 else (-1 if p % 3 == 2 else 0)
        for i, v in enumerate(values):
            if v < p2:
                break
            j = pos[v // p]
            total[i] -= total[j] - count_before
            character[i] -= chi_p * (character[j] - character_before)
        count_before += 1
        character_before += chi_p

    pi = {v: total[i] for i, v in enumerate(values)}
    pi1 = {v: (total[i] + character[i] - int(v >= 3)) // 2
           for i, v in enumerate(values)}
    pi1_small = [0] * (limit + 1)
    pi3_small = [0] * (limit + 1)
    c1 = c3 = 0
    for x in range(limit + 1):
        if x >= 2 and sieve[x]:
            if x % 3 == 1:
                c1 += 1
            elif x == 3:
                c3 += 1
        pi1_small[x] = c1
        pi3_small[x] = c3
    return primes, pi, pi1, pi1_small, pi3_small


def count_good_sequences(N: int, M: int) -> int:
    """Count sequences whose product is at most N and has divisor sum divisible by 3."""
    if N <= 1:
        return 0

    primes, pi, pi1, pi1_small, pi3_small = _prime_data(N)
    root = isqrt(N)
    weights = [1] * 35
    for e in range(1, 35):
        weights[e] = weights[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    def prime_counts(x):
        if x <= root:
            return pi1_small[x], pi3_small[x]
        return pi1[x], int(x >= 3)

    @lru_cache(maxsize=None)
    def F(x, first_idx):
        if x <= 1:
            return (1, 1)
        previous_prime = primes[first_idx - 1] if first_idx else 1
        cutoff = min(x, max(previous_prime, isqrt(x)))
        if cutoff >= x:
            all_tail = bad_tail = 0
        else:
            all_tail = M * (pi[x] - bisect_right(primes, cutoff))
            c1x, c3x = prime_counts(x)
            c1c, c3c = prime_counts(cutoff)
            bad_tail = M * ((c1x - c1c) + (c3x - c3c))
        all_answer = (1 + all_tail) % MOD
        bad_answer = (1 + bad_tail) % MOD

        end = bisect_right(primes, isqrt(x))
        for idx in range(first_idx, end):
            p = primes[idx]
            power = p
            exponent = 1
            residue = p % 3
            while power <= x:
                child_all, child_bad = F(x // power, idx + 1)
                coeff = weights[exponent]
                all_answer = (all_answer + coeff * child_all) % MOD
                if not ((residue == 1 and (exponent + 1) % 3 == 0) or
                        (residue == 2 and exponent % 2 == 1)):
                    bad_answer = (bad_answer + coeff * child_bad) % MOD
                if power > x // p:
                    break
                power *= p
                exponent += 1
        return all_answer, bad_answer

    all_sum, bad_sum = F(N, 0)
    return (all_sum - bad_sum) % MOD

