def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count ordered self-avoiding walks of K moves starting on any empty cell."""
    neighbors = [[] for _ in range(H * W)]
    empty = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != ".":
                continue
            v = r * W + c
            empty.append(v)
            if r > 0 and grid[r - 1][c] == ".":
                neighbors[v].append(v - W)
            if r + 1 < H and grid[r + 1][c] == ".":
                neighbors[v].append(v + W)
            if c > 0 and grid[r][c - 1] == ".":
                neighbors[v].append(v - 1)
            if c + 1 < W and grid[r][c + 1] == ".":
                neighbors[v].append(v + 1)

    # A bit mask makes the visited-cell check inexpensive, including on 10x10 grids.
    def extend(v: int, remaining: int, visited: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[v]:
            bit = 1 << nxt
            if not visited & bit:
                total += extend(nxt, remaining - 1, visited | bit)
        return total

    return sum(extend(start, K, 1 << start) for start in empty)

