def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a**b for b >= 2."""
    import math

    # A perfect power has at least one prime exponent. Inclusion-exclusion
    # over those exponents counts each value greater than one exactly once.
    limit = n.bit_length() - 1

    def primes_up_to(k: int) -> list[int]:
        sieve = bytearray(b"\x01") * (k + 1)
        if k >= 0:
            sieve[0] = 0
        if k >= 1:
            sieve[1] = 0
        for p in range(2, math.isqrt(k) + 1):
            if sieve[p]:
                start = p * p
                sieve[start:k + 1:p] = b"\x00" * (((k - start) // p) + 1)
        return [p for p in range(2, k + 1) if sieve[p]]

    def floor_root(value: int, exponent: int) -> int:
        if exponent == 2:
            return math.isqrt(value)
        # Binary search with capped multiplication to avoid large intermediates.
        lo, hi = 1, 1 << ((value.bit_length() + exponent - 1) // exponent)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            product = 1
            for _ in range(exponent):
                product *= mid
                if product > value:
                    break
            if product <= value:
                lo = mid
            else:
                hi = mid - 1
        return lo

    primes = primes_up_to(limit)
    total = 1  # 1 is a perfect power for every exponent b >= 2.
    # For a squarefree product m of prime exponents, the intersection is the
    # set of m-th powers. It is empty beyond base 1 once m > log2(n).
    for m in range(2, limit + 1):
        selected = [p for p in primes if m % p == 0]
        if not selected:
            continue
        product = 1
        for p in selected:
            product *= p
        if product != m:
            continue
        sign = 1 if len(selected) % 2 else -1
        total += sign * (floor_root(n, m) - 1)
    return total

