from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by
    their digit sum.
    """

    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        n = len(digits)
        total = 0

        # Fix the digit sum, then track the product modulo that sum. This keeps
        # the state small even though the actual digit product can be large.
        for target_sum in range(1, 9 * n + 1):
            @lru_cache(None)
            def dp(pos: int, remaining: int, product_mod: int,
                   started: bool, tight: bool) -> int:
                if remaining < 0 or remaining > 9 * (n - pos):
                    return 0
                if pos == n:
                    return int(started and remaining == 0 and product_mod == 0)

                limit = digits[pos] if tight else 9
                ways = 0
                for digit in range(limit + 1):
                    next_started = started or digit != 0
                    next_remaining = remaining - (digit if next_started else 0)
                    if next_started:
                        next_product = (product_mod * digit) % target_sum if started else digit % target_sum
                    else:
                        next_product = product_mod
                    ways += dp(pos + 1, next_remaining, next_product,
                               next_started, tight and digit == limit)
                return ways

            total += dp(0, target_sum, 1 % target_sum, False, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

