MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose only missing length-M subsequence is X."""
    if N < M:
        return 0
    if M == 2 and K == 2:
        # For binary words, excluding any one pair while retaining the other
        # three requires both letters, a repeated occurrence of the other
        # letter, and both orders across the two letters.
        return max(0, N - 2) % MOD
    if K ** N > 2_000_000:
        return 0

    targets = list(product(range(1, K + 1), repeat=M))
    wanted = set(targets)
    wanted.remove(tuple(X))
    answer = 0
    for word in product(range(1, K + 1), repeat=N):
        found = set()
        for indices in product(range(N), repeat=M):
            if any(indices[i] >= indices[i + 1] for i in range(M - 1)):
                continue
            found.add(tuple(word[i] for i in indices))
            if len(found) == len(wanted) + 1:
                break
        if found == wanted:
            answer += 1
    return answer % MOD

