from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def is_horizontal(i, j):
        return (i - j) % 2 == 0

    def strip(i, j, x, y):
        return y - j * K if is_horizontal(i, j) else x - i * K

    sk = strip(si, sj, S_x, S_y)
    tk = strip(ti, tj, T_x, T_y)
    if (si, sj) == (ti, tj):
        return min(abs(sk - tk), 2)

    di, dj = ti - si, tj - sj
    block_distance = abs(di) + abs(dj)

    if block_distance > 2000:
        return 2 * max(abs(di), abs(dj)) + (block_distance & 1)

    def useful_strips(i, j):
        if K <= 200:
            return range(K)
        values = {0, K - 1}
        if (i, j) == (si, sj):
            values.add(sk)
        if (i, j) == (ti, tj):
            values.add(tk)
        return values

    start = (si, sj, sk)
    goal = (ti, tj, tk)
    distances = {start: 0}
    queue = [(block_distance, 0, start)]

    def relax(node, cost, current):
        candidate = current + cost
        if candidate < distances.get(node, 10**100):
            distances[node] = candidate
            estimate = abs(node[0] - ti) + abs(node[1] - tj)
            heappush(queue, (candidate + estimate, candidate, node))

    while queue:
        _, cost, (i, j, k) = heappop(queue)
        if cost != distances.get((i, j, k)):
            continue
        if (i, j, k) == goal:
            return cost

        horizontal = is_horizontal(i, j)
        for q in useful_strips(i, j):
            if q != k:
                relax((i, j, q), abs(q - k), cost)

        if horizontal:
            relax((i - 1, j, K - 1), 1, cost)
            relax((i + 1, j, 0), 1, cost)
            if k == 0:
                for q in useful_strips(i, j - 1):
                    relax((i, j - 1, q), 1, cost)
            if k == K - 1:
                for q in useful_strips(i, j + 1):
                    relax((i, j + 1, q), 1, cost)
        else:
            relax((i, j - 1, K - 1), 1, cost)
            relax((i, j + 1, 0), 1, cost)
            if k == 0:
                for q in useful_strips(i - 1, j):
                    relax((i - 1, j, q), 1, cost)
            if k == K - 1:
                for q in useful_strips(i + 1, j):
                    relax((i + 1, j, q), 1, cost)

    return 2 * max(abs(di), abs(dj)) + (block_distance & 1)

