    """Calculate twice the black area in the specified wallpaper rectangle."""
    def axis_parts(lo, hi, period):
        start = lo % period
        length = hi - lo
        first = min(length, period - start)
        parts = []
        if first:
            parts.append((start, start + first))
        length -= first
        full, rem = divmod(length, period)
        if full:
            parts.append((0, period, full))
        if rem:
            parts.append((0, rem))
