from itertools import combinations, product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """ Count the number of sequences of length N consisting of integers from 1 to K,
    such that among all sequences of length M consisting of integers from 1 to K,
    the only sequence that cannot be obtained as a (not necessarily contiguous)
    subsequence is the given sequence X.

    The result should be returned modulo 998244353.
    """
    required = [M] * K
    if len(X) == M and all(v == X[0] for v in X):
        required[X[0] - 1] -= 1
    if N < sum(required):
        return 0

    if M == 2:
        def choose(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            ans = 1
            for t in range(1, b + 1):
                ans = ans * (a - t + 1) // t
            return ans % MOD

        def onto(q: int, length: int) -> int:
            if length < q:
                return 0
            ans = 0
            for i in range(q + 1):
                term = choose(q, i) * pow(q - i, length, MOD)
                ans += -term if i & 1 else term
            return ans % MOD

        q = tuple(X)
        if q[0] == q[1]:
            return sum(onto(K - 1, i) * onto(K - 1, N - 1 - i)
                       for i in range(N)) % MOD

        onto_values = [onto(K - 1, i) for i in range(N)]
        outer = [0] * N
        for i in range(N):
            for j in range(N - i):
                outer[i + j] = (outer[i + j] +
                                onto_values[i] * onto_values[j]) % MOD
        powers = [pow(K - 2, i, MOD) for i in range(N)]
        return sum(outer[t] * powers[N - 2 - t]
                   for t in range(N - 1)) % MOD

    if M == 3:
        q = tuple(X[:2])
        x = X[2]
        qsize = K - 1

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            out = 1
            for j in range(1, b + 1):
                out = out * (a - j + 1) // j
            return out % MOD

        def surjections(alphabet_size: int, length: int) -> int:
            if length < 0 or length < alphabet_size:
                return 0
            total = 0
            for i in range(alphabet_size + 1):
                term = comb(alphabet_size, i) * pow(alphabet_size - i, length, MOD)
                total += -term if i & 1 else term
            return total % MOD

        prefix_count = [0] * N
        surj = [surjections(qsize, j) for j in range(N + 1)]
        if q[0] != q[1]:
            pair_conv = [0] * (N + 1)
            for i in range(N + 1):
                for j in range(N + 1 - i):
                    pair_conv[i + j] = (pair_conv[i + j] + surj[i] * surj[j]) % MOD
            powers = [pow(K - 2, i, MOD) for i in range(N + 1)]
            for p in range(2, N):
                prefix_count[p] = sum(
                    pair_conv[t] * powers[p - 2 - t]
                    for t in range(p - 1)
                ) % MOD
        else:
            for p in range(N):
                prefix_count[p] = sum(
                    surj[i] * surj[p - 1 - i] for i in range(p)
                ) % MOD

        suffix_count = [0] * N
        if q[1] == x:
            suffix_count = surj[:N]
        else:
            for length in range(N):
                suffix_count[length] = sum(
                    pow(K - 2, j, MOD) * surj[length - j - 1]
                    for j in range(length)
                ) % MOD

        return sum(prefix_count[p] * suffix_count[N - p - 1]
                   for p in range(N)) % MOD

    # Exact finite-state DP for larger M. The bitset records which length-M
    # words have appeared; the suffix is enough to create new subsequences
    # when the next symbol is appended.
    word_count = K ** M
    wanted = ((1 << word_count) - 1)
    x_id = 0
    for value in X:
        x_id = x_id * K + (value - 1)
    wanted ^= 1 << x_id
    suffix_modulus = K ** max(0, M - 2)
    states = {(0, 0, 0): 1}
    for _ in range(N):
        following = {}
        for (seen, suffix, suffix_len), ways in states.items():
            for digit in range(K):
                new_seen = seen
                if suffix_len == M - 1:
                    new_seen |= 1 << (suffix * K + digit)
                new_len = min(M - 1, suffix_len + 1)
                if suffix_len < M - 1:
                    new_suffix = suffix * K + digit
                else:
                    new_suffix = (suffix % suffix_modulus) * K + digit
                key = (new_seen, new_suffix, new_len)
                following[key] = (following.get(key, 0) + ways) % MOD
        states = following
    return sum(ways for (seen, _, _), ways in states.items()
               if seen == wanted) % MOD

