from functools import lru_cache
from math import isqrt


@lru_cache(maxsize=None)
def _square_signature_counts(n: int) -> dict[str, int]:
    """Return the count of squares for each n-digit multiset including padding."""
    counts: dict[str, int] = {}
    for root in range(isqrt(10**n - 1) + 1):
        signature = "".join(sorted(str(root * root).zfill(n)))
        counts[signature] = counts.get(signature, 0) + 1
    return counts


def count_square_permutations(n: int, s: str) -> int:
    """Count unique square numbers obtainable by permuting the digits of s.

    Leading zeros are allowed in a permutation, so a square's usual decimal
    representation is padded with zeros to length n before comparing digits.
    """
    return _square_signature_counts(n).get("".join(sorted(s)), 0)

from functools import lru_cache
from math import isqrt


_WIDTH = 13


def _packed_square_signature(square: int) -> int:
    """Encode the square's digits, padded with zeros, in four-bit counters."""
    signature = 0
    length = 0
    while square:
        signature += 1 << (4 * (square % 10))
        square //= 10
        length += 1
    if length == 0:
        signature += 1
        length = 1
    return signature + (_WIDTH - length)


@lru_cache(maxsize=None)
def _square_signature_counts(n: int) -> dict[int, int]:
    """Count squares by their digit multiset, padded to the maximum width."""
    counts: dict[int, int] = {}
    for root in range(isqrt(10**n - 1) + 1):
        signature = _packed_square_signature(root * root)
        counts[signature] = counts.get(signature, 0) + 1
    return counts


def count_square_permutations(n: int, s: str) -> int:
    """Count unique square numbers obtainable by permuting the digits of s.

    Leading zeros are allowed in a permutation, so a square's usual decimal
    representation is padded with zeros to length n before comparing digits.
    """
    target = _WIDTH - n
    for digit in s:
        target += 1 << (4 * int(digit))
    return _square_signature_counts(n).get(target, 0)
